-- origin=auto row_preserving=True check=rows_equal
CREATE VIEW v_hero_attribute AS SELECT hero_attribute.hero_id AS hero_id, hero_attribute.attribute_id AS attribute_id, hero_attribute.attribute_value AS attribute_value, hero.superhero_name AS superhero_name, hero.full_name AS full_name, hero.gender_id AS gender_id, hero.eye_colour_id AS eye_colour_id, hero.hair_colour_id AS hair_colour_id, hero.skin_colour_id AS skin_colour_id, hero.race_id AS race_id, hero.publisher_id AS publisher_id, hero.alignment_id AS alignment_id, hero.height_cm AS height_cm, hero.weight_kg AS weight_kg, hero_skin_colour.colour AS colour, hero_race.race AS race, hero_publisher.publisher_name AS publisher_name, hero_hair_colour.colour AS hero_hair_colour, hero_gender.gender AS gender, hero_eye_colour.colour AS hero_eye_colour, hero_alignment.alignment AS alignment, attribute.attribute_name AS attribute_name FROM hero_attribute LEFT JOIN superhero AS hero ON hero_attribute.hero_id = hero.id LEFT JOIN colour AS hero_skin_colour ON hero.skin_colour_id = hero_skin_colour.id LEFT JOIN race AS hero_race ON hero.race_id = hero_race.id LEFT JOIN publisher AS hero_publisher ON hero.publisher_id = hero_publisher.id LEFT JOIN colour AS hero_hair_colour ON hero.hair_colour_id = hero_hair_colour.id LEFT JOIN gender AS hero_gender ON hero.gender_id = hero_gender.id LEFT JOIN colour AS hero_eye_colour ON hero.eye_colour_id = hero_eye_colour.id LEFT JOIN alignment AS hero_alignment ON hero.alignment_id = hero_alignment.id LEFT JOIN attribute AS attribute ON hero_attribute.attribute_id = attribute.id;

-- origin=auto row_preserving=True check=rows_equal
CREATE VIEW v_hero_power AS SELECT hero_power.hero_id AS hero_id, hero_power.power_id AS power_id, power.power_name AS power_name, hero.superhero_name AS superhero_name, hero.full_name AS full_name, hero.gender_id AS gender_id, hero.eye_colour_id AS eye_colour_id, hero.hair_colour_id AS hair_colour_id, hero.skin_colour_id AS skin_colour_id, hero.race_id AS race_id, hero.publisher_id AS publisher_id, hero.alignment_id AS alignment_id, hero.height_cm AS height_cm, hero.weight_kg AS weight_kg, hero_skin_colour.colour AS colour, hero_race.race AS race, hero_publisher.publisher_name AS publisher_name, hero_hair_colour.colour AS hero_hair_colour, hero_gender.gender AS gender, hero_eye_colour.colour AS hero_eye_colour, hero_alignment.alignment AS alignment FROM hero_power LEFT JOIN superpower AS power ON hero_power.power_id = power.id LEFT JOIN superhero AS hero ON hero_power.hero_id = hero.id LEFT JOIN colour AS hero_skin_colour ON hero.skin_colour_id = hero_skin_colour.id LEFT JOIN race AS hero_race ON hero.race_id = hero_race.id LEFT JOIN publisher AS hero_publisher ON hero.publisher_id = hero_publisher.id LEFT JOIN colour AS hero_hair_colour ON hero.hair_colour_id = hero_hair_colour.id LEFT JOIN gender AS hero_gender ON hero.gender_id = hero_gender.id LEFT JOIN colour AS hero_eye_colour ON hero.eye_colour_id = hero_eye_colour.id LEFT JOIN alignment AS hero_alignment ON hero.alignment_id = hero_alignment.id;

-- origin=auto row_preserving=True check=rows_equal
CREATE VIEW v_superhero AS SELECT superhero.id AS id, superhero.superhero_name AS superhero_name, superhero.full_name AS full_name, superhero.gender_id AS gender_id, superhero.eye_colour_id AS eye_colour_id, superhero.hair_colour_id AS hair_colour_id, superhero.skin_colour_id AS skin_colour_id, superhero.race_id AS race_id, superhero.publisher_id AS publisher_id, superhero.alignment_id AS alignment_id, superhero.height_cm AS height_cm, superhero.weight_kg AS weight_kg, skin_colour.colour AS colour, race.race AS race, publisher.publisher_name AS publisher_name, hair_colour.colour AS hair_colour, gender.gender AS gender, eye_colour.colour AS eye_colour, alignment.alignment AS alignment FROM superhero LEFT JOIN colour AS skin_colour ON superhero.skin_colour_id = skin_colour.id LEFT JOIN race AS race ON superhero.race_id = race.id LEFT JOIN publisher AS publisher ON superhero.publisher_id = publisher.id LEFT JOIN colour AS hair_colour ON superhero.hair_colour_id = hair_colour.id LEFT JOIN gender AS gender ON superhero.gender_id = gender.id LEFT JOIN colour AS eye_colour ON superhero.eye_colour_id = eye_colour.id LEFT JOIN alignment AS alignment ON superhero.alignment_id = alignment.id;
